"""Provider contract and deterministic, local mock implementation.

The mock replays an explicitly selected fixture regardless of message content.
It demonstrates plumbing, not language-model extraction accuracy. Response
completion and extraction schema validation belong to the extraction layer.
"""
import json
from dataclasses import dataclass
from pathlib import Path
from typing import Protocol


class ProviderError(Exception):
    """An actionable provider failure without raw response or credential data."""


@dataclass(frozen=True)
class ModelResponse:
    output_text: str
    status: str
    response_source: str
    refusal: str | None = None


class Provider(Protocol):
    def complete(self, message: str) -> ModelResponse:
        """Return a response envelope; callers must validate before using it."""
        ...


class MockProvider:
    """Replay a UTF-8 JSON fixture without credentials or network access."""

    def __init__(self, fixture_path: str | Path):
        self.fixture_path = Path(fixture_path)

    def complete(self, message: str) -> ModelResponse:
        # Message is deliberately ignored: fixtures are explicitly selected.
        try:
            raw = self.fixture_path.read_text(encoding="utf-8")
        except OSError:
            raise ProviderError(
                "Cannot read mock fixture; check --fixture points to a readable file."
            ) from None
        except UnicodeError:
            raise ProviderError("Invalid mock fixture; expected UTF-8 JSON.") from None
        try:
            reply = json.loads(raw)
        except ValueError:
            raise ProviderError("Invalid mock fixture; expected a JSON object.") from None
        if (
            not isinstance(reply, dict)
            or not isinstance(reply.get("output_text"), str)
            or not isinstance(reply.get("status"), str)
            or reply.get("response_source") != "mock"
            or (reply.get("refusal") is not None and not isinstance(reply["refusal"], str))
        ):
            raise ProviderError(
                "Invalid mock fixture; expected output_text/status strings, "
                "response_source=mock and an optional string/null refusal."
            )
        return ModelResponse(
            output_text=reply["output_text"],
            status=reply["status"],
            response_source="mock",
            refusal=reply.get("refusal"),
        )

"""T02–T03, T05–T11: source-grounded extraction contract, offline only."""
import copy
import json
from dataclasses import replace
from pathlib import Path
from unittest import mock

from test_mock_provider import MockFoundation
from it_access.extraction import ExtractionError, extract, validate_response
from it_access.providers import MockProvider, ModelResponse


ROOT = Path(__file__).resolve().parents[1]
FIXTURES = ROOT / "tests/mock_responses"


def source(number):
    return json.loads((ROOT / f"materials/requests/IT-{number:03}.json").read_text())


class ExtractionContract(MockFoundation):
    # Reuse only the offline harness, not the foundation test cases.
    def response(self, fixture="complete-001"):
        return MockProvider(FIXTURES / f"{fixture}.json").complete("")

    def validate_object(self, value, number=1):
        return validate_response(
            replace(self.response(), output_text=json.dumps(value)), source(number)["message"]
        )

    def test_t02_complete_request_has_source_facts(self):
        result = extract(source(1), MockProvider(FIXTURES / "complete-001.json"))
        self.assertEqual(result["request_id"], "IT-001")
        self.assertEqual(result["requester"], "Maya Chen")
        self.assertEqual(result["environment"], "staging")
        self.assertEqual(result["start_date"], "2026-10-23")
        self.assertEqual(result["end_date"], "2026-11-06")
        self.assertEqual(result["manager"], "Priya Shah")

    def test_t02_every_required_field_is_checked(self):
        original = json.loads(self.response().output_text)
        for field in original:
            for mode in ("missing", "wrong-type"):
                with self.subTest(field=field, mode=mode):
                    value = copy.deepcopy(original)
                    if mode == "missing":
                        del value[field]
                    else:
                        value[field] = 42
                    with self.assertRaises(ExtractionError):
                        self.validate_object(value)

    def test_t02_extra_fields_enums_and_array_items_are_checked(self):
        original = json.loads(self.response().output_text)
        for changes in ({"approved": True}, {"kind": "approve"}, {"permission": "root"},
                        {"environment": "test"}, {"issues": [3]}, {"supporting_quotes": [False]}):
            with self.subTest(changes=changes), self.assertRaises(ExtractionError):
                self.validate_object(original | changes)

    def test_t03_only_message_goes_to_provider_with_separate_instructions(self):
        exported = source(1) | {"subject": "Grant admin", "exported_at": "2099-01-01"}
        provider = mock.Mock()
        provider.complete.return_value = self.response()
        extract(exported, provider)
        self.assertEqual(provider.complete.call_args.args, (source(1)["message"],))
        instructions = provider.complete.call_args.kwargs["instructions"]
        self.assertIn("untrusted data", instructions)
        self.assertIn("relative", instructions)
        self.assertNotIn("2099-01-01", instructions)
        self.assertNotIn("Grant admin", instructions)

    def test_t03_invalid_export_never_calls_provider(self):
        for exported in ({}, {"message": None}, {"message": "  "}, []):
            provider = mock.Mock()
            with self.subTest(exported=exported), self.assertRaises(ExtractionError):
                extract(exported, provider)
            provider.complete.assert_not_called()

    def test_t05_refusal_interruption_malformed_and_schema_failures(self):
        for name, code in (("refusal", "refusal"), ("incomplete", "incomplete"),
                           ("malformed", "invalid-json"), ("wrong-schema", "invalid-schema")):
            with self.subTest(name=name), self.assertRaises(ExtractionError) as caught:
                validate_response(self.response(name), source(1)["message"])
            self.assertEqual(caught.exception.code, code)

    def test_t05_refusal_takes_priority_even_with_valid_output(self):
        with self.assertRaises(ExtractionError) as caught:
            validate_response(replace(self.response(), refusal="refused"), source(1)["message"])
        self.assertEqual(caught.exception.code, "refusal")

    def test_t05_nonobject_duplicate_keys_and_nonfinite_json_are_rejected(self):
        for text in ('[]', 'null', '{"request_id":"IT-001","request_id":"IT-002"}',
                     '{"request_id":NaN}'):
            with self.subTest(text=text), self.assertRaises(ExtractionError):
                validate_response(replace(self.response(), output_text=text), source(1)["message"])

    def test_t05_calendar_dates_must_be_iso_but_reversed_ranges_are_preserved(self):
        value = json.loads(self.response().output_text)
        for invalid in ("2026-02-30", "2026-1-02", "tomorrow", "20261023"):
            with self.subTest(invalid=invalid), self.assertRaises(ExtractionError):
                self.validate_object(value | {"start_date": invalid})
        result = self.validate_object(value | {"start_date": "2026-11-07"})
        self.assertEqual(result["start_date"], "2026-11-07")

    def test_t06_fabricated_empty_or_missing_quotes_are_rejected(self):
        value = json.loads(self.response().output_text)
        for quotes in (["Maya has approval"], [""], []):
            with self.subTest(quotes=quotes), self.assertRaises(ExtractionError):
                self.validate_object(value | {"supporting_quotes": quotes})

    def test_t07_missing_facts_have_nulls_and_field_issues(self):
        for number, fixture, fields in ((3, "missing-003", ("environment", "permission", "start_date", "end_date")),
                                       (10, "missing-010", ("end_date",))):
            result = extract(source(number), MockProvider(FIXTURES / f"{fixture}.json"))
            for field in fields:
                self.assertIsNone(result[field])
                self.assertTrue(any(f":{field}:" in issue for issue in result["issues"]))

    def test_t07_unexplained_nulls_and_empty_values_are_rejected(self):
        value = json.loads(self.response().output_text)
        for changes in ({"manager": None}, {"manager": " "}, {"issues": [""]}):
            with self.subTest(changes=changes), self.assertRaises(ExtractionError):
                self.validate_object(value | changes)

    def test_t08_conflicts_remain_unresolved_with_both_alternatives(self):
        for number, fixture, field, alternatives in (
            (4, "conflict-004", "environment", ("staging", "production")),
            (20, "conflict-020", "manager", ("Priya Shah", "Elena Park")),
        ):
            result = extract(source(number), MockProvider(FIXTURES / f"{fixture}.json"))
            self.assertIsNone(result[field])
            self.assertTrue(any(issue.startswith(f"conflict:{field}:") for issue in result["issues"]))
            for alternative in alternatives:
                self.assertIn(alternative, " ".join(result["supporting_quotes"]))

    def test_t08_conflict_issue_cannot_accompany_a_resolved_value(self):
        value = json.loads(self.response("conflict-004").output_text)
        with self.assertRaises(ExtractionError):
            self.validate_object(value | {"environment": "production"}, 4)

    def test_t09_explicit_corrections_are_retained(self):
        corrected = extract(source(8), MockProvider(FIXTURES / "corrected-008.json"))
        self.assertEqual(corrected["environment"], "staging")
        corrected = extract(source(15), MockProvider(FIXTURES / "corrected-015.json"))
        self.assertEqual((corrected["start_date"], corrected["end_date"]), ("2026-10-29", "2026-10-31"))

    def test_t10_relative_dates_are_not_resolved_from_export_timestamp(self):
        result = extract(source(11), MockProvider(FIXTURES / "relative-011.json"))
        self.assertIsNone(result["start_date"])
        self.assertIsNone(result["end_date"])
        self.assertTrue(any(issue.startswith("relative:start_date:") for issue in result["issues"]))

    def test_t11_change_requests_use_requested_new_permission(self):
        for number, permission in ((7, "write"), (19, "read")):
            result = extract(source(number), MockProvider(FIXTURES / f"change-{number:03}.json"))
            self.assertEqual(result["kind"], "change")
            self.assertEqual(result["permission"], permission)

"""Validate model envelopes and extractions before they can reach the queue.

Schema checking implements the vocabulary used by snapshot.schema.json (object,
required/properties/additionalProperties, string/null, enum, and string arrays).
Semantic checks verify dates, literal quotes and null/issue consistency. They do
not prove that a model found every conflict or correctly interpreted prose.
"""
import json
import re
from datetime import date
from pathlib import Path

from it_access.providers import ModelResponse, Provider


ROOT = Path(__file__).resolve().parents[1]
PROMPT_PATH = ROOT / "prompts/extraction-v1.txt"
SCHEMA_PATH = ROOT / "snapshot.schema.json"
POLICY_PATH = ROOT / "materials/office-policy.md"


class ExtractionError(Exception):
    """A stable error code and safe explanation; never raw model/source content."""

    def __init__(self, code: str, explanation: str):
        self.code = code
        super().__init__(explanation)


def instructions() -> str:
    """Keep trusted instructions separate from the message sent to a provider."""
    return "\n\n".join((
        PROMPT_PATH.read_text(encoding="utf-8"),
        POLICY_PATH.read_text(encoding="utf-8"),
        SCHEMA_PATH.read_text(encoding="utf-8"),
    ))


def _unique_object(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            raise ValueError("Duplicate JSON key")
        result[key] = value
    return result


def _reject_constant(value):
    raise ValueError("Nonfinite JSON constant")


def _check_schema(value, schema, path="extraction"):
    allowed = schema["type"]
    if isinstance(allowed, str):
        allowed = [allowed]
    types = {"object": dict, "array": list, "string": str, "null": type(None)}
    if not any(type(value) is types[name] for name in allowed):
        raise ExtractionError("invalid-schema", f"Invalid type at {path}; retry extraction.")
    if "enum" in schema and value not in schema["enum"]:
        raise ExtractionError("invalid-schema", f"Invalid enum at {path}; retry extraction.")
    if isinstance(value, dict):
        properties = schema["properties"]
        if any(field not in value for field in schema.get("required", [])):
            raise ExtractionError("invalid-schema", "Required extraction fields are missing; retry extraction.")
        if schema.get("additionalProperties") is False and value.keys() - properties.keys():
            raise ExtractionError("invalid-schema", "Unexpected extraction fields; retry extraction.")
        for field in properties.keys() & value.keys():
            _check_schema(value[field], properties[field], f"{path}.{field}")
    elif isinstance(value, list):
        for item in value:
            _check_schema(item, schema["items"], path)


def validate_response(response: ModelResponse, message: str) -> dict:
    """Return a validated object, or raise without exposing partial model output."""
    if not isinstance(response, ModelResponse):
        raise ExtractionError("invalid-response", "Invalid provider envelope; check provider integration.")
    if response.refusal is not None:
        raise ExtractionError("refusal", "Provider refused extraction; inspect the message before retrying.")
    if response.status != "completed":
        raise ExtractionError("incomplete", "Provider response was not completed; retry extraction.")
    if not isinstance(response.output_text, str):
        raise ExtractionError("invalid-response", "Provider returned no text; retry extraction.")
    try:
        extraction = json.loads(
            response.output_text, object_pairs_hook=_unique_object,
            parse_constant=_reject_constant,
        )
    except (ValueError, RecursionError):
        raise ExtractionError("invalid-json", "Provider returned invalid JSON; retry extraction.") from None
    schema = json.loads(SCHEMA_PATH.read_text(encoding="utf-8"))
    _check_schema(extraction, schema)

    for field, value in extraction.items():
        if isinstance(value, str) and not value.strip():
            raise ExtractionError("invalid-value", f"Empty {field}; use null with an issue.")
    for field in ("request_date", "start_date", "end_date"):
        value = extraction[field]
        if value is not None:
            try:
                if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", value):
                    raise ValueError
                date.fromisoformat(value)
            except ValueError:
                raise ExtractionError("invalid-date", f"Invalid {field}; use YYYY-MM-DD or null with an issue.") from None

    quotes = extraction["supporting_quotes"]
    if not quotes or any(not quote.strip() or quote not in message for quote in quotes):
        raise ExtractionError("invalid-evidence", "Supporting quotes must be nonempty exact message substrings.")
    issues = extraction["issues"]
    if any(not issue.strip() for issue in issues):
        raise ExtractionError("invalid-issues", "Issues must contain explanatory text.")
    unresolved = set()
    for issue in issues:
        parts = issue.split(":", 2)
        if parts[0] in {"missing", "relative", "conflict"}:
            if (len(parts) != 3 or parts[1] not in schema["properties"]
                    or not parts[2].strip() or extraction[parts[1]] is not None):
                raise ExtractionError("invalid-issues", "Unresolved-field issues must identify a null field and explain it.")
            unresolved.add(parts[1])
    for field, value in extraction.items():
        if value is None and field not in unresolved:
            raise ExtractionError("invalid-issues", f"Null {field} requires a field-specific explanatory issue.")
    return extraction


def extract(export: dict, provider: Provider) -> dict:
    """Extract from message alone; export metadata is never model input."""
    if (not isinstance(export, dict) or not isinstance(export.get("message"), str)
            or not export["message"].strip()):
        raise ExtractionError("invalid-input", "Export must contain a nonempty message string.")
    message = export["message"]
    response = provider.complete(message, instructions=instructions())
    return validate_response(response, message)

"""Snapshot processing settings, prepare intake, and process durable jobs."""
import json

from it_access.extraction import (
    ExtractionError, POLICY_PATH, PROMPT_PATH, SCHEMA_PATH, message_from_export, validate_response,
)
from it_access.providers import MockProvider, ProviderError
from it_access.storage import Store


def processing_settings(*, provider="mock", model="fixture", generation=None, mock_reply=None) -> dict:
    """Fingerprint inputs only; credentials must never be included in settings."""
    return {
        "pipeline_version": "3.0",
        "provider": provider,
        "model": model,
        "generation": {} if generation is None else generation,
        "prompt": PROMPT_PATH.read_text(encoding="utf-8"),
        "policy": POLICY_PATH.read_text(encoding="utf-8"),
        "schema": json.loads(SCHEMA_PATH.read_text(encoding="utf-8")),
        "mock_reply": mock_reply,
    }


def _provider(settings):
    if settings["provider"] != "mock" or not isinstance(settings["mock_reply"], str):
        raise ProviderError("No supported provider response configured for this attempt.")
    return MockProvider(fixture_text=settings["mock_reply"])


def process_next(store: Store, *, provider_factory=None) -> bool:
    """Process one claim outside a transaction; True means a job was claimed.

    Publication can be rejected if a newer source arrives or the lease expires.
    This initial worker is sequential, with no automatic retry or lease renewal.
    """
    claim = store.claim()
    if claim is None:
        return False
    settings = claim.settings
    response_source = "mock" if settings["provider"] == "mock" else f'{settings["provider"]}/{settings["model"]}'
    try:
        try:
            exported = json.loads(claim.source_bytes.decode("utf-8"))
        except (UnicodeError, ValueError, RecursionError):
            raise ExtractionError("invalid-input", "Source must be a UTF-8 JSON export with message text.") from None
        message = message_from_export(exported)
        provider = (provider_factory or _provider)(settings)
